// Bounce service worker — installable + offline app (thecreateco Wave 4 PWA pattern).
// GENERATED by pwa/build-sw.mjs from pwa/sw.template.js — edit those, then rebuild.
//
// - Precaches the Bounce app shell (/browser/ and its CSS/JS/icons). VERSION is a hash of
//   every precached file, so any change to them produces a new worker and a new cache.
// - Navigations are network-first (3 s timeout); offline they fall back to the cached copy
//   of that page, then to the app shell (other pages redirect to /browser/).
// - NEVER cached: user files (they're read in the page and never fetched through here), audio of any kind (including the demo studies) and .bounce exports,
//   and every cross-origin request — except the public thecreateco suite kit script
//   (shared app menu), cached stale-while-revalidate so the menu draws offline.
// - Updates never take over mid-session: the waiting worker only calls skipWaiting() when
//   the page posts {type:'SKIP_WAITING'}, sent only after the user clicks "Reload" on the
//   "Update available" prompt (/pwa.js). Kill switch: pwa/kill-switch-sw.js.
const VERSION = '777140f8e4ab';
const SHELL_URL = '/browser/';
const PRECACHE = ["/browser/","/site.css","/test/bounce.js","/test/bounce-project.js","/test/common.js","/test/touch.css","/favicon.svg","/pwa.js","/manifest.webmanifest","/icons/icon-192.png","/icons/icon-512.png","/icons/icon-maskable-192.png","/icons/icon-maskable-512.png"];
const PREFIX = 'bounce';
const SHELL = `${PREFIX}-shell-${VERSION}`;
const PAGES = `${PREFIX}-pages`;
const SUITE = 'tcc-suite-kit';
const KEEP = new Set([SHELL, PAGES, SUITE]);
const NEVER = new RegExp("^/assets/audio/|^/assets/after-hours/outputs/|\\.(wav|mp3|m4a|aac|flac|ogg|oga|aif|aiff|mp4|mov|zip|bounce)$");

self.addEventListener('install', event => {
  event.waitUntil(caches.open(SHELL).then(cache => cache.addAll(PRECACHE.map(url => new Request(url, { cache: 'reload' })))));
});

self.addEventListener('activate', event => {
  event.waitUntil(caches.keys()
    .then(keys => Promise.all(keys.filter(key => (key.startsWith(`${PREFIX}-`) || key === SUITE) && !KEEP.has(key)).map(key => caches.delete(key))))
    .then(() => self.clients.claim()));
});

self.addEventListener('message', event => {
  if (event.data && event.data.type === 'SKIP_WAITING') self.skipWaiting();
});

const timeout = ms => new Promise((_, reject) => setTimeout(() => reject(new Error('timeout')), ms));

async function navigation(request) {
  const url = new URL(request.url);
  const key = url.origin + url.pathname;
  try {
    const response = await Promise.race([fetch(request), timeout(3000)]);
    if (response.ok && !response.redirected && (response.headers.get('content-type') || '').includes('text/html')) {
      const copy = response.clone();
      caches.open(PAGES).then(cache => cache.put(key, copy)).catch(() => {});
    }
    return response;
  } catch {
    const cached = (await caches.match(key, { cacheName: PAGES })) || (url.pathname === SHELL_URL ? await caches.match(SHELL_URL, { cacheName: SHELL }) : null);
    if (cached) return cached;
    if (url.pathname.startsWith(SHELL_URL)) return (await caches.match(SHELL_URL, { cacheName: SHELL })) || Response.error();
    return Response.redirect(SHELL_URL, 302);
  }
}

async function precached(request) {
  const hit = await caches.match(request, { cacheName: SHELL });
  return hit || fetch(request);
}

async function staleWhileRevalidate(request) {
  const cache = await caches.open(SUITE);
  const hit = await cache.match(request);
  const network = fetch(request).then(response => { if (response.ok || response.type === 'opaque') cache.put(request, response.clone()).catch(() => {}); return response; }).catch(() => hit || Response.error());
  return hit || network;
}

self.addEventListener('fetch', event => {
  const request = event.request;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin === 'https://thecreatingco.com' && url.pathname.startsWith('/suite/v1/') && /\.(js|json|css)$/.test(url.pathname)) {
    event.respondWith(staleWhileRevalidate(request));
    return;
  }
  if (url.origin !== self.location.origin) return; // cross-origin: network only, never cached
  if (NEVER.test(url.pathname)) return; // user-data-like / large media: network only, never cached
  if (request.mode === 'navigate') { event.respondWith(navigation(request)); return; }
  if (PRECACHE.includes(url.pathname)) { event.respondWith(precached(request)); return; }
  // everything else same-origin: network only (not cached)
});
